  `Spin Coating Speed Passivator` int NULL DEFAULT NULL,
  `Spin Coating Time Passivator` int NULL DEFAULT NULL,
  `Passivator Dropping Timing` int NULL DEFAULT NULL,
  `Passivator Volume` int NULL DEFAULT NULL,
  `Annealed Temperature Passivator` int NULL DEFAULT NULL,
  `Annealed Time Passivator` int NULL DEFAULT NULL,
  `PCE` decimal(6, 4) NULL DEFAULT NULL,
  `FF` decimal(6, 4) NULL DEFAULT NULL,
  `Voc` decimal(6, 4) NULL DEFAULT NULL,
  `Jsc` decimal(6, 4) NULL DEFAULT NULL,
  `filename` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `area_px2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `mean_RGB` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `gray_mean` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `sample_id` int NULL DEFAULT NULL,
  PRIMARY KEY (`index`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 50796 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

