-- ----------------------------
-- Table structure for no_characterisation_match
-- ----------------------------
DROP TABLE IF EXISTS `no_characterisation_match`;
CREATE TABLE `no_characterisation_match`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `analysis_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `reverse_diff_class` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `sample_id_1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `sample_id_2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `control_device_fabrication` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `target_device_fabrication` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `json_file_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `meta_info` json NULL COMMENT '原始 Meta Info 内容',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0=未使用，1=已作为任务提取',
  `version` int NULL DEFAULT NULL COMMENT '匹配的版本',
`json_filename` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci 
  GENERATED ALWAYS AS (trim(trailing '.json' from substring_index(`json_file_path`, '\\', -1))) STORED,
`task_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci 
  GENERATED ALWAYS AS (substring_index(substring_index(`json_file_path`, '\\', -2), '\\', 1)) STORED,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_match_unique`(`sample_id_1`, `sample_id_2`, `reverse_diff_class`, `analysis_type`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14398 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

